// JavaScript track — same Prisma schema DSL; Zod validates inputs at the JS boundary.
model LabCategory {
  id    Int       @id @default(autoincrement())
  name  String
  items LabItem[]
  @@map("lab_categories")
}

model LabItem {
  id         Int         @id @default(autoincrement())
  label      String
  categoryId Int         @map("category_id")
  category   LabCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)
  @@map("lab_items")
}

